29: /* A prepared message is dependent on the Loop, so it belongs here */
30: struct PreparedMessage {
31:     /* These should be a single alloation along with the PreparedMessage itself (they are static) */
32:     std::string originalMessage, compressedMessage;
33:     bool compressed;
34:     int opCode;
35: };
