37: struct Loop {
38: private:
39:     static void wakeupCb(us_loop_t *loop) {
40:         LoopData *loopData = (LoopData *) us_loop_ext(loop);
41: 
42:         /* Swap current deferQueue */
43:         loopData->deferMutex.lock();
44:         int oldDeferQueue = loopData->currentDeferQueue;
45:         loopData->currentDeferQueue = (loopData->currentDeferQueue + 1) % 2;
46:         loopData->deferMutex.unlock();
